from queueing import payload

DEFAULT_BATCH_SIZE = 20


def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise ValueError("batch_size must be an integer between 1 and 100")
    if not 1 <= batch_size <= 100:
        raise ValueError("batch_size must be an integer between 1 and 100")
    return enqueue(payload(owner, batch_size=batch_size))

import api
from queueing import payload
from worker import execute


def test_submit_default_batch_size():
    seen = {}
    def enqueue(payload_):
        seen.update(payload_)
        return "ok"
    result = api.submit("alice", enqueue)
    assert result == "ok"
    assert seen["owner"] == "alice"
    assert seen["batch_size"] == 20


def test_submit_explicit_batch_size():
    seen = {}
    def enqueue(payload_):
        seen.update(payload_)
        return "ok"
    api.submit("bob", enqueue, batch_size=42)
    assert seen["batch_size"] == 42


def test_submit_validation_before_enqueue():
    def enqueue(payload_):
        raise AssertionError("enqueue should not be called")
    for bad in (0, 101, True, 1.5, "10", None):
        try:
            api.submit("x", enqueue, batch_size=bad)
        except ValueError:
            pass
        else:
            raise AssertionError("expected ValueError for %r" % (bad,))


def test_legacy_payload_uses_default():
    task = payload("carol")
    assert execute(task, lambda owner, bs: (owner, bs)) == ("carol", 20)


def test_worker_uses_queued_batch_size():
    task = payload("dave", batch_size=7)
    assert execute(task, lambda owner, bs: (owner, bs)) == ("dave", 7)


def test_owner_preserved():
    task = payload("erin", batch_size=3)
    assert execute(task, lambda owner, bs: owner) == "erin"


